        Identity aaden = context.getObjectByName(Identity.class, "Amy.Cox");
        List<Link> allLinks = aaden.getLinks();
        for (Link link : allLinks) {
            String appName = link.getApplicationName();
            if (appName != null && appName.startsWith("ApplicationProfile")) {
                Application app = link.getApplication();
                String nativeId = link.getNativeIdentity();
                Attributes entitlementAttributes = link.getEntitlementAttributes();
                Object entitlementValuesObj = entitlementAttributes.get("entitlement");
                List entitlementValues = null;
                if (entitlementValuesObj instanceof List) {
                    entitlementValues = (List)entitlementValuesObj;
                } else {
                    entitlementValues = Collections.singletonList(entitlementValuesObj);
                }
                for (Object entitlementValue : entitlementValues) {
                    AttributeAssignment ass = new AttributeAssignment(app, nativeId, null, "entitlement", entitlementValue,"James.Smith", Source.LCM, Type.Entitlement);;
                    aaden.add(ass);
                }
            }
        }

        return aaden.toXml();

