	// directory where the stack files are written
	String fileNameBase = "/temp/ThreadDumps/ThreadDump";

	void dumpStacks(String fileName) throws IOException {
		ThreadMXBean mxBean = ManagementFactory.getThreadMXBean();
		ThreadInfo[] threadInfos = mxBean.getThreadInfo(mxBean.getAllThreadIds(), 0);
		Map threadInfoMap = new HashMap();
		for (ThreadInfo threadInfo : threadInfos) {
			threadInfoMap.put(threadInfo.getThreadId(), threadInfo);
		}

		// choose our dump-file
		File dumpFile = new File(fileName);
		Writer writer = new BufferedWriter(new FileWriter(dumpFile));
		try {
			dumpTraces(mxBean, threadInfoMap, writer);
            writer.write("Connections: " + connections + "\n");
		} finally {
            writer.flush();
			writer.close();
		}
	}

	void dumpTraces(ThreadMXBean mxBean, Map threadInfoMap, Writer writer)
			throws IOException {
		Map stacks = Thread.getAllStackTraces();
		writer.write("Dump of " + stacks.size() + " threads at "
				+ new SimpleDateFormat("yyyy/MM/dd HH:mm:ss z").format(new Date(System.currentTimeMillis())) + "\n\n");
		for (Map.Entry entry : stacks.entrySet()) {
			Thread thread = entry.getKey();
			writer.write("\"" + thread.getName() + "\" prio=" + thread.getPriority() + " tid=" + thread.getId() + " "
					+ thread.getState() + " " + (thread.isDaemon() ? "deamon" : "worker") + "\n");
			ThreadInfo threadInfo = threadInfoMap.get(thread.getId());
			if (threadInfo != null) {
				writer.write("    native=" + threadInfo.isInNative() + ", suspended=" + threadInfo.isSuspended()
						+ ", block=" + threadInfo.getBlockedCount() + ", wait=" + threadInfo.getWaitedCount() + "\n");
				writer.write("    lock=" + threadInfo.getLockName() + " owned by " + threadInfo.getLockOwnerName()
						+ " (" + threadInfo.getLockOwnerId() + "), cpu="
						+ (mxBean.getThreadCpuTime(threadInfo.getThreadId()) / 1000000L) + ", user="
						+ (mxBean.getThreadUserTime(threadInfo.getThreadId()) / 1000000L) + "\n");
			}
			for (StackTraceElement element : entry.getValue()) {
				writer.write("        ");
				writer.write(element.toString());
				writer.write("\n");
			}
			writer.write("\n");
		}
	}


      // faux main method
      String customName = "ThreadDumpConfig";
      String fileName = "";
      DebugBean dBean = new DebugBean();
      int i = 0;
      int connections = 0;
      Custom cfg = context.getObject(Custom.class, customName);
      if (cfg == null) {
        cfg = new Custom();
        cfg.setName(customName);
        cfg.put("sleep", DEFAULT_SLEEP);
        cfg.put("dump", true);
      }
      cfg.put("ctrl", true);
      context.saveObject(cfg);
      context.commitTransaction();
      boolean control = true;
      while (control) {
        control = cfg.getBoolean("ctrl");
        boolean dump = cfg.getBoolean("dump");
        int sleep = cfg.getInt("sleep");

        // always do this
        connections = context.getEnvironment().getActiveConnections();
        if (dump) {
            String fileName = fileNameBase + System.currentTimeMillis() + "-" + i + ".txt";
            log.warn("Dumping threads: " + fileName);
            dumpStacks(fileName);
        }

        context.decache();
        cfg = context.getObject(Custom.class, customName);

        log.warn("Sleep: " + sleep);
        log.warn("Control: " + control);
        log.warn("Connections: " + connections);
        i++;

        control = false;

}

